N = 40
solutions = []
for x in range(1, N + 1):
    for y in range(1, N + 1):
        z = x + y
        if z <= N:
            solutions.append((x, y, z))

print(f"Total number of solutions: {len(solutions)}")

# Analyze distribution of z (the sum)
z_counts = {}
for x, y, z in solutions:
    z_counts[z] = z_counts.get(z, 0) + 1

print("\nCounts for each value of z (where x+y=z):")
# Since z goes from 2 up to 40, we can print the counts in order
for z in range(2, N + 1):
    if z in z_counts:
        print(f"z={z}: {z_counts[z]} times")

# Analyze distribution of x and y (the summands) - optional, but useful for 'distribution analysis'
x_counts = {}
y_counts = {}
for x, y, z in solutions:
    x_counts[x] = x_counts.get(x, 0) + 1
    y_counts[y] = y_counts.get(y, 0) + 1

print("\nCounts for each x (first summand):")
# The distribution of x should be symmetrical to y if we don't distinguish order, but here the triple (x,y,z) is ordered.
# Since x+y=z, if we fix z, x determines y=z-x.
# If we fix z, x can range from 1 to z-1. There are z-1 solutions for a fixed z.
# The count for a specific x is related to how many z's it participates in.
# If x is fixed, y can be 1, 2, ..., N-x. So z can be x+1, ..., x+(N-x)=N.
# Number of solutions for a fixed x is N - x.
for x in range(1, N + 1):
    if x in x_counts:
        print(f"x={x}: {x_counts[x]} times")
print("\nCounts for each y (second summand):")
# Same logic, the count for y is N - y.
for y in range(1, N + 1):
    if y in y_counts:
        print(f"y={y}: {y_counts[y]} times")
